document.querySelectorAll('[data-lab="PM10-I1"]').forEach(root=>{const g=k=>root.querySelector('[data-field="'+k+'"]'),zh=root.dataset.lang==='zh';const update=()=>{const nu=+g('nu').value,s=+g('stretch').value,G=nu*8.314*298/1e6,stress=x=>G*(x-1/(x*x));g('nuo').textContent=nu+' mol/m³';g('so').textContent=s.toFixed(2);g('curve').setAttribute('d',Array.from({length:101},(_,i)=>(i?'L':'M')+(70+i*4.8)+' '+(340-stress(1+i*.02)/1.5*275)).join(' '));g('dot').setAttribute('cx',70+(s-1)*240);g('dot').setAttribute('cy',340-stress(s)/1.5*275);g('result').textContent=zh?'G = '+G.toFixed(4)+' MPa；拉伸比 '+s.toFixed(2)+' 对应工程应变 '+((s-1)*100).toFixed(0)+'%，公称应力 '+stress(s).toFixed(4)+' MPa。同一拉伸比下，有效承载链浓度加倍使本模型应力加倍；硬段质量比例本身不是这个浓度。':'G = '+G.toFixed(4)+' MPa. Stretch ratio '+s.toFixed(2)+' gives '+((s-1)*100).toFixed(0)+'% engineering strain and '+stress(s).toFixed(4)+' MPa nominal stress. At fixed stretch, doubling active strand concentration doubles model stress. Hard-block mass fraction itself is not this concentration.';};root.querySelectorAll('input').forEach(el=>el.addEventListener('input',update));update();});